const fs = require('fs');
const path = require('path');

// Default values
const DEFAULT_PORT = 3000;
const DEFAULT_HTTPS_PORT = 3443;

// Configuration object
const config = {
  port: process.env.PORT || DEFAULT_PORT,
  httpsPort: process.env.HTTPS_PORT || DEFAULT_HTTPS_PORT,
  tlsCertPath: process.env.TLS_CERT_PATH,
  tlsKeyPath: process.env.TLS_KEY_PATH,

  // Method to check if TLS certificates are available and readable
  hasValidTlsConfig() {
    if (!this.tlsCertPath || !this.tlsKeyPath) {
      return false;
    }

    try {
      // Check if certificate file exists and is readable
      fs.accessSync(this.tlsCertPath, fs.constants.R_OK);
      // Check if key file exists and is readable
      fs.accessSync(this.tlsKeyPath, fs.constants.R_OK);
      return true;
    } catch (error) {
      console.warn('TLS certificate or key not accessible:', error.message);
      return false;
    }
  },

  // Method to get TLS options for HTTPS server
  getTlsOptions() {
    if (!this.hasValidTlsConfig()) {
      return null;
    }

    return {
      cert: fs.readFileSync(this.tlsCertPath),
      key: fs.readFileSync(this.tlsKeyPath)
    };
  }
};

module.exports = config;

