const express = require('express');
const https = require('https');
const http = require('http');
const app = express();

// Import configuration
const config = require('./config');

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Start HTTP server
const httpServer = http.createServer(app);
httpServer.listen(config.port, () => {
  console.log(`HTTP Server running on port ${config.port}`);
});

// Start HTTPS server if TLS configuration is valid
if (config.hasValidTlsConfig()) {
  try {
    const httpsOptions = config.getTlsOptions();
    const httpsServer = https.createServer(httpsOptions, app);

    httpsServer.listen(config.httpsPort, () => {
      console.log(`HTTPS Server running on port ${config.httpsPort}`);
    });

    // Handle HTTPS server errors
    httpsServer.on('error', (error) => {
      console.error('HTTPS server error:', error);
    });

  } catch (error) {
    console.error('Failed to start HTTPS server:', error.message);
    console.log('Continuing with HTTP only');
  }
} else {
  console.log('TLS certificates not available - running HTTP only');
}

module.exports = app;

